<?php

declare(strict_types=1);

namespace Domain\Documents\Calls;

use App\AgentRequests\Contracts\CallSender;
use App\AgentRequests\Support\CallKey;
use App\AgentRequests\Values\CallAccepted;
use App\Text\Support\TextSelection;
use Domain\Documents\Data\DocumentList;
use Domain\Documents\Data\DraftView;
use Domain\Documents\Data\RecordInspection;
use Domain\Documents\Data\RecordText;
use Domain\Documents\Data\ReportList;
use Domain\Documents\Data\RevisionView;
use Domain\Documents\Enums\AttentionFilter;

/**
 * The signed calls of Documents, generated by php artisan journal:calls; run it again instead of editing.
 */
final readonly class DocumentCalls
{
    public function __construct(private CallSender $sender) {}

    public function closeDocument(
        string $number,
        string $token,
        int $version,
        CallKey $requestKey = new CallKey(),
    ): DraftClosed {
        return $this->sender->send(CloseDocumentCall::from([
            'number' => $number,
            'token' => $token,
            'version' => $version,
            'requestKey' => $requestKey,
        ]));
    }

    public function editDocument(
        string $number,
        string $token,
        int $version,
        string $mode,
        string|null $section,
        string|null $body,
        string|null $old,
        string|null $new,
        string|null $title,
        string|null $abstract,
        CallKey $requestKey = new CallKey(),
    ): DraftHeld {
        return $this->sender->send(EditDocumentCall::from([
            'number' => $number,
            'token' => $token,
            'version' => $version,
            'mode' => $mode,
            'section' => $section,
            'body' => $body,
            'old' => $old,
            'new' => $new,
            'title' => $title,
            'abstract' => $abstract,
            'requestKey' => $requestKey,
        ]));
    }

    public function editReport(
        string $number,
    ): CallAccepted {
        return $this->sender->send(EditReportCall::from([
            'number' => $number,
        ]));
    }

    public function inspectDocument(
        string $number,
    ): RecordInspection {
        return $this->sender->send(InspectDocumentCall::from([
            'number' => $number,
        ]));
    }

    public function inspectReport(
        string $number,
    ): RecordInspection {
        return $this->sender->send(InspectReportCall::from([
            'number' => $number,
        ]));
    }

    public function listDocumentRevisions(
        string $number,
        int $page = 1,
    ): RevisionList {
        return $this->sender->send(ListDocumentRevisionsCall::from([
            'number' => $number,
            'page' => $page,
        ]));
    }

    public function listDocuments(
        AttentionFilter $attention = AttentionFilter::Active,
        int $page = 1,
        string|null $query = null,
        bool $revisions = false,
        string|null $after = null,
    ): DocumentList {
        return $this->sender->send(ListDocumentsCall::from([
            'attention' => $attention,
            'page' => $page,
            'query' => $query,
            'revisions' => $revisions,
            'after' => $after,
        ]));
    }

    public function listReports(
        AttentionFilter $attention = AttentionFilter::Active,
        int $page = 1,
        string|null $query = null,
        string|null $after = null,
    ): ReportList {
        return $this->sender->send(ListReportsCall::from([
            'attention' => $attention,
            'page' => $page,
            'query' => $query,
            'after' => $after,
        ]));
    }

    /**
     * @param  list<string>  $about
     */
    public function makeDocument(
        string $title,
        string $abstract,
        string $body,
        array $about,
        CallKey $requestKey = new CallKey(),
    ): RecordFiled {
        return $this->sender->send(MakeDocumentCall::from([
            'title' => $title,
            'abstract' => $abstract,
            'body' => $body,
            'about' => $about,
            'requestKey' => $requestKey,
        ]));
    }

    /**
     * @param  list<string>  $about
     */
    public function makeReport(
        string $title,
        string $abstract,
        string $body,
        array $about,
        CallKey $requestKey = new CallKey(),
    ): RecordFiled {
        return $this->sender->send(MakeReportCall::from([
            'title' => $title,
            'abstract' => $abstract,
            'body' => $body,
            'about' => $about,
            'requestKey' => $requestKey,
        ]));
    }

    public function openDocument(
        string $number,
        CallKey $requestKey = new CallKey(),
    ): DraftHeld {
        return $this->sender->send(OpenDocumentCall::from([
            'number' => $number,
            'requestKey' => $requestKey,
        ]));
    }

    public function settleDocument(
        string $number,
        string $reason,
        int $revision,
        CallKey $requestKey = new CallKey(),
    ): CallAccepted {
        return $this->sender->send(SettleDocumentCall::from([
            'number' => $number,
            'reason' => $reason,
            'revision' => $revision,
            'requestKey' => $requestKey,
        ]));
    }

    public function settleReport(
        string $number,
        string $reason,
        CallKey $requestKey = new CallKey(),
    ): CallAccepted {
        return $this->sender->send(SettleReportCall::from([
            'number' => $number,
            'reason' => $reason,
            'requestKey' => $requestKey,
        ]));
    }

    public function showDocument(
        string $number,
        TextSelection $selection = new TextSelection(),
        int|null $revision = null,
        int|null $atRevision = null,
    ): RecordText {
        return $this->sender->send(ShowDocumentCall::from([
            'number' => $number,
            'selection' => $selection,
            'revision' => $revision,
            'atRevision' => $atRevision,
        ]));
    }

    public function showDocumentRevision(
        string $number,
        int $revision,
    ): RevisionView {
        return $this->sender->send(ShowDocumentRevisionCall::from([
            'number' => $number,
            'revision' => $revision,
        ]));
    }

    public function showDraft(
        string $number,
    ): DraftView {
        return $this->sender->send(ShowDraftCall::from([
            'number' => $number,
        ]));
    }

    public function showReport(
        string $number,
        TextSelection $selection = new TextSelection(),
    ): RecordText {
        return $this->sender->send(ShowReportCall::from([
            'number' => $number,
            'selection' => $selection,
        ]));
    }
}
